def check_identity(ident,cfg,v,t,r,s):
    expected={'candidate_id':v['candidate_id'],'candidate_content_sha256':v['model_tensor_content_sha256'],'task':t,'representation':r,'cv_seed':s,'protocol_semantic_sha256':cfg['protocol_semantic_sha256'],'source_identity_sha256':cfg['producer_source_identity_sha256'],'cpu_runtime_lock_sha256':cfg['cpu_runtime_lock_sha256'],'feature_dtype':'float32','width':1920}
    need(all(ident.get(k)==x for k,x in expected.items()),'Wrong checkpoint/task/layer/seed/protocol/source binding')
    fc=cfg['producer_config']['feature_config'];need(ident['TRAIN_cohort_sha256']==fc['cohorts'][t]['train']['ordered_metadata_sha256'] and ident['DEV_cohort_sha256']==fc['cohorts'][t]['dev']['ordered_metadata_sha256'],'Wrong cohort binding');need(ident['fold_sha256']==next(x['sha256'] for x in fc['folds'][t] if x['cv_seed']==s),'Wrong fold binding')

def producer_provenance(c,cfg,v,a,t,r,s,rows):
    root=Path(cfg['producer_artifacts_root'])/'candidates'/a/'tasks'/t/'production'/key(r)/('seed'+str(s));seal=verify_seal(root,required=['head.joblib','PARAMETERS.npz','SUMMARY.json','CV_INDEX.json']);summary=load(root/'SUMMARY.json');check_identity(seal['identity'],cfg,v,t,r,s);headid=select(rows,'final_head',r=r,s=s,p='independent_refit')['id'];need(summary['planned_spec_id']==headid==seal['identity']['planned_spec_id'] and not summary['dev_used_for_selection'],'Wrong final TRAIN fitting identity')
    train,y,ids=matrix(str(c),a,t,r,'train');fs=fold_indices(cfg,t,s,ids);calls=load(root/'CV_INDEX.json')['calls'];need(len(calls)==16 and len({x['planned_spec_id'] for x in calls})==16,'Missing/duplicate CV calls');traces=[];retries=0;inputhashes={}
    for e in calls:
        row=next((x for x in rows if x['id']==e['planned_spec_id']),None);need(row and row['k']=='optimizer_call' and row['r']==r and row['s']==s,'Unexpected optimizer key');cr=root/e['relative_root'];need(sha(cr/'COMPLETE.json')==e['receipt_sha256'],'CV receipt changed');cs=verify_seal(cr,required=['model.joblib','TRACE.json']);tr=load(cr/'TRACE.json');check_identity(tr['identity'],cfg,v,t,r,s);need(cs['identity']==tr['identity'] and tr['identity']['planned_spec_id']==row['id'] and tr['TRAIN_only'],'CV call identity changed')
        fold=row.get('fold');j=row.get('j');ix=np.arange(len(y)) if fold is None else fs[fold][0]
        if fold not in inputhashes:inputhashes[fold]=(hashlib.sha256(train[ix].tobytes()).hexdigest(),hashlib.sha256(y[ix].tobytes()).hexdigest(),digest([ids[k] for k in ix]))
        need((tr['fit_input_sha256'],tr['fit_labels_sha256'],tr['identity']['training_IDs_sha256'])==inputhashes[fold],'CV actual fitting rows/features/labels changed');need(tr['fit_rows']==len(ix),'CV fitting denominator changed');need(sorted(set(y[ix].tolist()))==summary['class_order'],'Fitting class missing')
        need(tr['identity']['fold']==fold and tr['C']==(summary['selected_C'] if fold is None else [.1,1.,10.][j]),'CV C/fold mismatch')
        if fold is not None:
            need(tr['identity']['validation_IDs_sha256']==digest([ids[k] for k in fs[fold][1]]),'Validation row IDs changed');need(tr['validation_AUROC']==summary['CV'][j]['fold_AUROC'][fold],'CV summary disconnected from call')
        history=tr['attempts'];need(len(history) in [1,2] and history[0]['max_iter']==2000 and not history[-1]['warnings'],'Unresolved/invalid convergence history')
        if len(history)==2:need(history[1]['max_iter']==10000 and history[0]['warnings'] and all(w['category']=='ConvergenceWarning' for w in history[0]['warnings']),'Unapproved retry rule')
        for h in history:need(all(0<int(n)<=h['max_iter'] for n in h['n_iter']),'Invalid iteration accounting')
        need(len(history)==e['optimizer_calls'],'Actual call count mismatch');retries+=len(history)-1;traces.append({'planned_spec_id':row['id'],'receipt_sha256':sha(cr/'COMPLETE.json'),'trace_sha256':sha(cr/'TRACE.json'),'attempts':history,'fold':fold,'C':tr['C']})
    for i,b in enumerate(summary['CV']):need(b['C']==[.1,1.,10.][i] and len(b['fold_AUROC'])==5 and b['mean_fold_AUROC']==float(np.mean(b['fold_AUROC'])),'Wrong CV candidate/mean')
    selected=choose(summary['CV']);need(selected==summary['selected_C'] and summary['initial_optimizer_calls']==16 and summary['actual_optimizer_calls']==16+retries and summary['retries']==retries,'C tie-breaking/call counts changed')
    model=joblib.load(root/'head.joblib');need(sha(root/'head.joblib')==summary['head_serialization_sha256'] and parameter_hash(model)==summary['parameter_content_sha256'],'Saved head content mismatch');need(model[-1].classes_.tolist()==summary['class_order'] and model[0].n_features_in_==1920,'Head class/feature mismatch')
    with np.load(root/'PARAMETERS.npz',allow_pickle=False) as z:
        for k,x in [('scaler_mean',model[0].mean_),('scaler_scale',model[0].scale_),('scaler_var',model[0].var_),('coef',model[-1].coef_),('intercept',model[-1].intercept_),('classes',model[-1].classes_)]:need(np.array_equal(z[k],x),'PARAMETERS and estimator disagree')
    public=load(Path(cfg['producer_public_root'])/'candidates'/a/t/'PROBE_INDEX.json')['records'];pub=next(x for x in public if x['planned_spec_id']==headid);need(pub['artifact_sha256']==sha(root/'COMPLETE.json') and pub['parameter_content_sha256']==parameter_hash(model) and pub['head_sha256']==sha(root/'head.joblib'),'Producer public/private join mismatch')
    return root,model,{'planned_spec_id':headid,'producer_receipt_sha256':sha(root/'COMPLETE.json'),'head_sha256':sha(root/'head.joblib'),'parameter_content_sha256':parameter_hash(model),'selected_C':selected,'initial_optimizer_calls':16,'actual_optimizer_calls':16+retries,'retries':retries,'call_records':traces,'fresh_refit_performed_by_this_check':False}

def probability(c,cfg,v,a,t,r,s,policy,rows,headroot=None,headmodel=None):
    root=Path(cfg['producer_artifacts_root'])/'candidates'/a/'tasks'/t/'probabilities'/key(r)/('seed'+str(s))/policy;seal=verify_seal(root,required=['predictions.npz','draws.npz','METRICS.json']);m=load(root/'METRICS.json');ident=m['identity'];check_identity(ident,cfg,v,t,r,s);pid=select(rows,'prediction',r=r,s=s,p=policy,split='dev')['id'];need(ident['planned_spec_id']==pid and ident['policy']==policy and ident['split']=='dev','Probability path/policy changed');x,y,ids=matrix(str(c),a,t,r,'dev');rr=meta(cfg,t,'dev');classes=np.array(cfg['producer_config']['feature_config']['cohorts'][t]['dev']['class_order'])
    if policy=='independent_refit':path=headroot/'head.joblib';model=headmodel
    else:
        path,ref=original(cfg,t,r,s);model=joblib.load(path);ap=Path(cfg['producer_artifacts_root'])/'candidates'/a/'tasks'/t/'fixed-applications'/key(r)/('seed'+str(s));aseal=verify_seal(ap,required=['APPLICATION.json']);ar=load(ap/'APPLICATION.json');check_identity(ar,cfg,v,t,r,s);need(ar['planned_spec_id']==select(rows,'fixed_application',r=r,s=s,p=policy)['id'] and ar['prediction_planned_spec_id']==pid and ar['new_reference_fits']==0 and ar['target_recentering_or_recalibration'] is False and ar['head_sha256']==ref['head_sha256'],'Fixed-original policy changed')
    before=sha(path);need(before==ident['head_sha256'] and parameter_hash(model)==ident['head_parameter_content_sha256'] and model[-1].classes_.tolist()==classes.tolist(),'Saved scaler/head/column mismatch');independent=reconstruct(model,x);need(independent.dtype==np.float64,'Reconstruction dtype changed')
    with np.load(root/'predictions.npz',allow_pickle=False) as z:
        need(z['ids'].tolist()==ids and z['labels'].tolist()==y.tolist() and z['groups'].tolist()==[x['group'] for x in rr] and z['classes'].tolist()==classes.tolist(),'Prediction row/class/group ordering mismatch');p=z['probabilities'];need(p.dtype==np.float64 and p.shape==(512,len(classes)),'Probability dtype/shape changed');prob=compare(independent,p,1e-10,pid)
    w,drawsha=weights(str(c),t);need(drawsha==ident['dev_draw_sha256'],'Wrong draw reference');points,pvalid=independent_metrics(y,p,classes,np.ones((1,len(y))));draws,valid=independent_metrics(y,p,classes,w);need(bool(pvalid[0]),'Undefined primary point');expected={select(rows,'classifier_metric',r=r,s=s,p=policy,split='dev',m=name)['id'] for name in METRICS};need({row['planned_spec_id'] for row in m['metrics']}==expected and len(m['metrics'])==5,'Duplicate/missing/extra metric identities');metricrows=[];checks=[]
    with np.load(root/'draws.npz',allow_pickle=False) as z:
        need(set(z.files)==set(METRICS)|{n+'_valid' for n in METRICS},'Unexpected draw arrays')
        for row in m['metrics']:
            cr=row['canonical_metric'];name=cr['metric'];d=draws[MAP[name]];mask=valid&np.isfinite(d);saved=z[name];sm=z[name+'_valid'];need(mask.dtype==sm.dtype==np.bool_ and np.array_equal(mask,sm),'Validity mask mismatch');need(d.shape==saved.shape==(2000,) and saved.dtype==np.float64,'Draw vector shape/dtype mismatch');need(np.isnan(d[~mask]).all() and np.isnan(saved[~mask]).all(),'Invalid values changed to finite values');need(hashlib.sha256(saved.tobytes()).hexdigest()==row['bootstrap_vector_sha256'] and hashlib.sha256(sm.tobytes()).hexdigest()==row['valid_mask_sha256'],'Producer draw/mask byte identity mismatch');need(cr['draw_sha256']==drawsha and cr['sample_count']==512 and cr['group_count']==len({x['group'] for x in rr}) and cr['bootstrap_attempted']==2000 and cr['bootstrap_valid']==int(mask.sum()) and cr['bootstrap_invalid']==int((~mask).sum()),'Metric denominator/group/draw identity changed');pc=compare(points[MAP[name]],[cr['estimate']],1e-12,name+'_point');cc=[pc]
            if mask.any():cc+=[compare(d[mask],saved[mask],1e-12,name+'_draw'),compare(np.percentile(d[mask],[2.5,97.5],method='linear'),[cr['ci_low'],cr['ci_high']],1e-12,name+'_CI')]
            else:need(cr['ci_low'] is None and cr['ci_high'] is None and cr['missing_reason'],'Undefined interval not explicit')
            checks+=cc;metricrows.append({'planned_spec_id':row['planned_spec_id'],'source_row_id':row['source_row_id'],'metric':name,'checks':cc,'estimate':float(points[MAP[name]][0]),'interval':None if not mask.any() else np.percentile(d[mask],[2.5,97.5],method='linear').tolist(),'attempted':2000,'valid':int(mask.sum()),'invalid':int((~mask).sum()),'computed_vector_sha256':hashlib.sha256(d.tobytes()).hexdigest(),'producer_vector_sha256':row['bootstrap_vector_sha256'],'computed_mask_sha256':hashlib.sha256(mask.tobytes()).hexdigest(),'producer_metric_sha256':sha(root/'METRICS.json')})
    need(sha(path)==before and parameter_hash(model)==ident['head_parameter_content_sha256'],'Reference/head mutated during check');pub=next(x for x in load(Path(cfg['producer_public_root'])/'candidates'/a/t/'PREDICTION_INDEX.json')['records'] if x['planned_spec_id']==pid);need(pub['artifact_sha256']==sha(root/'COMPLETE.json') and pub['probability_value_sha256']==hashlib.sha256(p.tobytes()).hexdigest(),'Public saved-probability join changed')
    prediction=(p[:,1]>=.5).astype(int) if len(classes)==2 else np.argmax(p,axis=1);confusion=np.zeros((len(classes),len(classes)),dtype=np.int64);np.add.at(confusion,(y,prediction),1);wrong=prediction!=y;true=p[np.arange(len(y)),y];ce=-np.log(np.clip(true,np.finfo(np.float64).eps,1-np.finfo(np.float64).eps))
    return {'status':'PASS','alias':a,'task':t,'representation':r,'cv_seed':s,'policy':policy,'split':'dev','planned_spec_id':pid,'producer_receipt_sha256':sha(root/'COMPLETE.json'),'producer_identity_sha256':digest(ident),'head_sha256':before,'parameter_content_sha256':parameter_hash(model),'probability_value_sha256':hashlib.sha256(p.tobytes()).hexdigest(),'probability_check':prob,'metric_records':metricrows,'draw_sha256':drawsha,'class_order':classes.tolist(),'rows':512,'groups':len({x['group'] for x in rr}),'metric_probability_endpoint':'Exact producer float64 probabilities after independent function check','diagnostics':{'outcome_informed_not_preregistered':True,'confusion_matrix':confusion.tolist(),'predicted_class_counts':np.bincount(prediction,minlength=len(classes)).tolist(),'balanced_accuracy_exactly_half':bool(points['balanced_accuracy'][0]==.5),'single_predicted_class':bool(len(np.unique(prediction))==1),'confident_wrong_above_0_99':int(np.sum(wrong&(p.max(1)>.99))),'clipped_true_probability_count':int(np.sum(true<np.finfo(np.float64).eps)),'max_row_cross_entropy':float(ce.max())},'max_metric_draw_CI_abs_residual':max(x['max_abs_residual'] for x in checks),'new_fits':0}

def unit(c,a,t,r,s):
    cfg,v=ready(c,a,t,r,s);base=Path(cfg['artifacts_root'])/'candidates'/a;out=base/'verification'/t/key(r)/('seed'+str(s));ident={'phase':'S08','alias':a,'task':t,'representation':r,'cv_seed':s,'source_identity_sha256':cfg['_source'],'config_sha256':sha(Path(c)/'RUN_CONFIG.json'),'producer_source_identity_sha256':cfg['producer_source_identity_sha256'],'runtime_lock_sha256':cfg['cpu_runtime_lock_sha256']};started=time.monotonic();cpu=time.process_time()
    with exclusive(base/'locks'/(t+'-'+key(r)+'-seed'+str(s)+'.lock')),threadpool_limits(limits=4):
        if (out/'COMPLETE.json').exists():verify_seal(out,ident,required=['VERIFICATION.json']);return load(out/'VERIFICATION.json')
        need(not out.exists(),'Preserve incomplete verifier output; explicit repair required');out.mkdir(parents=True);rows=specs(str(c),a,t);head,model,provenance=producer_provenance(c,cfg,v,a,t,r,s,rows);paths=[probability(c,cfg,v,a,t,r,s,p,rows,head,model) for p in POLICIES];rss=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024;need(rss<=cfg['worker_RSS_limit_bytes'],'Worker RSS exceeded');audit=next((x for x in audit_keys(str(c)) if x['k']=='audit_refit' and (x['c'],x['t'],x['r'],x['s'])==(a,t,r,s)),None)
        result={'schema_version':'s08-independent-unit-v1','status':'PASS_NUMERICAL_CHECKS_PENDING_AUDIT_RECOVERY_RELEASE','identity':ident,'head':provenance,'paths':paths,'audit_panel_member':audit is not None,'planned_audit_spec_id':None if audit is None else audit['id'],'producer_key_ids':[x['id'] for x in rows if x.get('r')==r and x.get('s')==s],'wall_seconds':time.monotonic()-started,'CPU_process_seconds':time.process_time()-cpu,'peak_RSS_bytes':rss,'owned_process':process_identity(),'independence':'Direct float32-preserving scaler/linear/logistic reconstruction plus pairwise/rank-threshold metrics. Shared NumPy/SciPy/BLAS, joblib/sklearn object decoding and original frozen estimator specification; independent input/group/fold adapters. No producer predict/metric calls.','S09_executed':False};need(len(result['producer_key_ids'])==30,'Wrong exact unit key count');put(out/'VERIFICATION.json',result);write_seal(out,ident,['VERIFICATION.json'],{'heads':1,'applications':1,'paths':2,'metrics':10,'producer_calls_checked':16});print('S08_SAVED_UNIT_PASS',a,t,r,s,flush=True);return result
